// Poiema UI behaviors — optional, dependency-free, SSR-safe (nothing runs on import).
//
// Every behavior has the same shape:  behavior(element, options?) -> { destroy() }
// which is exactly a Svelte action, and trivial to call from a React effect,
// a Vue directive or plain JS. init() wires them all up from data-pm-* attributes.

const mq = (q) => typeof matchMedia === 'function' && matchMedia(q).matches;
const reducedMotion = () => mq('(prefers-reduced-motion: reduce)');
const noop = { destroy() {} };
const attr = (el, name, fallback) => (el.hasAttribute(name) ? el.getAttribute(name) : fallback);

/** Rise + fade into place the first time the element scrolls into view. */
export function reveal(node, { threshold = 0.1, rootMargin = '0px 0px -5% 0px', once = true } = {}) {
  const show = () => node.setAttribute('data-pm-in', '');
  if (reducedMotion() || typeof IntersectionObserver === 'undefined') { show(); return noop; }
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (e.isIntersecting) { show(); if (once) io.disconnect(); }
      else if (!once) node.removeAttribute('data-pm-in');
    }
  }, { threshold, rootMargin });
  io.observe(node);
  return { destroy: () => io.disconnect() };
}

/** Like reveal, but children enter one after another (80ms apart). */
export function stagger(node, options) {
  Array.from(node.children).forEach((child, i) => child.style.setProperty('--pm-i', String(i)));
  return reveal(node, options);
}

/** The first child leans toward the pointer. Hover-capable devices only. */
export function tilt(node, { max = 9, scale = 1.04 } = {}) {
  if (!mq('(hover: hover)') || reducedMotion()) return noop;
  const move = (e) => {
    const r = node.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width - 0.5;
    const y = (e.clientY - r.top) / r.height - 0.5;
    node.style.setProperty('--pm-tilt-y', `${(x * max * 2).toFixed(2)}deg`);
    node.style.setProperty('--pm-tilt-x', `${(-y * max * 2).toFixed(2)}deg`);
    node.style.setProperty('--pm-tilt-s', String(scale));
  };
  const leave = () => ['--pm-tilt-x', '--pm-tilt-y', '--pm-tilt-s'].forEach((p) => node.style.removeProperty(p));
  node.addEventListener('pointermove', move);
  node.addEventListener('pointerleave', leave);
  return { destroy() { node.removeEventListener('pointermove', move); node.removeEventListener('pointerleave', leave); leave(); } };
}

/** Cross-fade through the element's children ("material swap"). */
export function cycle(node, { interval = Number(attr(node, 'data-pm-cycle', '')) || 1800 } = {}) {
  const items = () => Array.from(node.children);
  let i = Math.max(0, items().findIndex((c) => c.hasAttribute('data-pm-active')));
  const set = (n) => items().forEach((c, k) => c.toggleAttribute('data-pm-active', k === n));
  set(i);
  if (reducedMotion() || items().length < 2) return noop;
  const id = setInterval(() => {
    if (typeof document !== 'undefined' && document.hidden) return;
    i = (i + 1) % items().length;
    set(i);
  }, interval);
  return { destroy: () => clearInterval(id) };
}

const announcing = new WeakMap(); // live region -> its pending timer

/**
 * Says `message` to screen readers. The region appears on first use, so a screen the server
 * rendered still matches when React hydrates it, and in the open dialog the button is in: a modal
 * makes the rest of the page inert, and a region out there would stay silent.
 */
function announce(node, message, lasts) {
  const host = node.closest('dialog[open]') ?? document.body;
  let region = host.querySelector(':scope > [data-pm-announcer]');
  if (!region) {
    region = document.createElement('div');
    region.className = 'pm-sr-only';
    region.setAttribute('data-pm-announcer', '');
    region.setAttribute('role', 'status');
    region.setAttribute('aria-live', 'polite');
    host.appendChild(region);
  }
  // Emptied now and written a moment later: many screen readers miss text set as a region appears,
  // and a repeat of what it already holds. Emptied again once the label is back, or someone
  // browsing later would still find "Copied ✓" at the end of the page.
  clearTimeout(announcing.get(region));
  region.textContent = '';
  announcing.set(region, setTimeout(() => {
    region.textContent = message;
    announcing.set(region, setTimeout(() => { region.textContent = ''; }, lasts));
  }, 100));
}

/** Copy text to the clipboard on click, briefly show "Copied ✓" in place of the label, and say it to screen readers. */
export function copy(node, {
  text,
  target = attr(node, 'data-pm-copy-target'),
  success = attr(node, 'data-pm-copied', 'Copied ✓'),
  failure = attr(node, 'data-pm-copy-failed', 'Could not copy'),
  duration = 2200,
} = {}) {
  let t;
  const click = async () => {
    const value = text ?? (attr(node, 'data-pm-copy', '') ||
      (target && document.querySelector(target)?.innerText) || '');
    // Nothing to copy is a failure: writing it would wipe the clipboard and claim success.
    let ok = value !== '';
    if (ok) { try { await navigator.clipboard.writeText(value); } catch { ok = false; } }
    const message = ok ? success : failure;
    node.setAttribute('data-pm-feedback', message);
    announce(node, message.replace(/\s*✓\s*/g, ''), duration); // read aloud it's just "check mark"
    clearTimeout(t);
    t = setTimeout(() => node.removeAttribute('data-pm-feedback'), duration);
  };
  node.addEventListener('click', click);
  return { destroy() { node.removeEventListener('click', click); clearTimeout(t); node.removeAttribute('data-pm-feedback'); } };
}

/** Whole days from now until `date` (never negative). */
export function daysUntil(date, now = new Date()) {
  return Math.max(0, Math.ceil((new Date(date).getTime() - now.getTime()) / 864e5));
}

/** Writes daysUntil(data-pm-countdown) into the element. In React/Vue/Svelte prefer daysUntil() in render. */
export function countdown(node, { to = attr(node, 'data-pm-countdown') } = {}) {
  if (to) node.textContent = String(daysUntil(to));
  return noop;
}

/**
 * Click opens a <dialog> by id: <button data-pm-open="invite">. If the id is on the page twice
 * (a framework keeping a hidden route mounted), it's the one on the visible screen that opens.
 */
export function opener(node, { target = attr(node, 'data-pm-open') } = {}) {
  const click = () => {
    const matches = document.querySelectorAll(`[id="${target}"]`);
    const shown = [...matches].find((el) => el.parentElement?.checkVisibility?.() !== false);
    (shown ?? matches[0])?.showModal?.();
  };
  node.addEventListener('click', click);
  return { destroy: () => node.removeEventListener('click', click) };
}

/**
 * <dialog class="pm-dialog | pm-sheet | pm-panel | pm-fabmenu">: closes on any [data-pm-close]
 * inside and on the backdrop. A sheet also drags down to close, because its grabber promises
 * that, and rises above the on-screen keyboard: phones shrink only the visual viewport, so
 * typing in a sheet fixed to the bottom would hide what it finds.
 */
export function dialog(node) {
  // A click on the backdrop has the dialog as its target. So does a press inside a field that
  // was dragged out past the edge to select text, which is why the press has to start outside.
  const onBackdrop = (e) => {
    if (e.target !== node) return false;
    if (node.classList.contains('pm-fabmenu')) return true; // it fills the screen
    const r = node.getBoundingClientRect();
    return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
  };
  let pressedOutside = false;
  const press = (e) => { pressedOutside = onBackdrop(e); };
  const click = (e) => {
    if (e.target.closest?.('[data-pm-close]')) node.close();
    else if (pressedOutside && onBackdrop(e)) node.close();
    pressedOutside = false;
  };
  node.addEventListener('pointerdown', press);
  node.addEventListener('click', click);

  const isSheet = node.classList.contains('pm-sheet');
  const vv = isSheet && typeof visualViewport !== 'undefined' ? visualViewport : null;
  const lift = () => {
    const inset = Math.max(0, Math.round(innerHeight - vv.height - vv.offsetTop));
    // Under ~80px it's the browser's address bar, not a keyboard.
    if (inset > 80) node.style.setProperty('--pm-keyboard-inset', `${inset}px`);
    else node.style.removeProperty('--pm-keyboard-inset');
  };
  vv?.addEventListener('resize', lift);
  vv?.addEventListener('scroll', lift);

  let dragFrom = null;
  const stopDrag = () => { dragFrom = null; node.style.removeProperty('transform'); };
  const touchstart = (e) => {
    const fromTop = e.touches[0].clientY - node.getBoundingClientRect().top;
    dragFrom = node.scrollTop === 0 && fromTop < 48 ? e.touches[0].clientY : null;
  };
  const touchmove = (e) => {
    if (dragFrom === null) return;
    const down = e.touches[0].clientY - dragFrom;
    if (down < 0) { stopDrag(); return; } // going up is a scroll, not a drag
    e.preventDefault();
    node.style.transform = `translateY(${down}px)`;
  };
  const touchend = (e) => {
    if (dragFrom === null) return;
    const far = e.changedTouches[0].clientY - dragFrom > 80;
    stopDrag();
    if (far) node.close();
  };
  if (isSheet) {
    node.addEventListener('touchstart', touchstart, { passive: true });
    node.addEventListener('touchmove', touchmove, { passive: false });
    node.addEventListener('touchend', touchend);
    node.addEventListener('touchcancel', stopDrag);
  }

  return {
    destroy() {
      node.removeEventListener('pointerdown', press);
      node.removeEventListener('click', click);
      vv?.removeEventListener('resize', lift);
      vv?.removeEventListener('scroll', lift);
      if (isSheet) {
        node.removeEventListener('touchstart', touchstart);
        node.removeEventListener('touchmove', touchmove);
        node.removeEventListener('touchend', touchend);
        node.removeEventListener('touchcancel', stopDrag);
      }
    },
  };
}

/** Empties the search field next to it and tells the app: <button data-pm-clear>. */
export function clear(node, { target = attr(node, 'data-pm-clear') } = {}) {
  const click = () => {
    const input = target ? document.querySelector(target) : node.closest('.pm-search')?.querySelector('input');
    if (!input) return;
    // Through the native setter, or React would not see the change as its own onChange.
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(input, '');
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.focus();
  };
  node.addEventListener('click', click);
  return { destroy: () => node.removeEventListener('click', click) };
}

/**
 * Places a popover menu under the button that opens it: <button popovertarget="more" data-pm-menu>.
 * Found by id when it opens, because a framework may replace the popover after this mounts.
 */
export function menu(node, { gap = 8 } = {}) {
  const mine = (e) => e.newState === 'open'
    && e.target.id === node.getAttribute('popovertarget')
    && node.checkVisibility?.() !== false; // the same id may be on a hidden route
  const place = (e) => {
    if (!mine(e)) return;
    const r = node.getBoundingClientRect();
    e.target.style.top = `${r.bottom + gap}px`;
    // clientWidth, not innerWidth: an always-on scrollbar isn't part of the page.
    e.target.style.right = `${Math.max(16, document.documentElement.clientWidth - r.right)}px`;
  };
  // Flips up only when it would leave the screen, once it has a height to measure.
  const flip = (e) => {
    if (!mine(e)) return;
    const r = node.getBoundingClientRect();
    const h = e.target.offsetHeight;
    if (r.bottom + gap + h > innerHeight) e.target.style.top = `${Math.max(16, r.top - gap - h)}px`;
  };
  document.addEventListener('beforetoggle', place, true);
  document.addEventListener('toggle', flip, true);
  return {
    destroy() {
      document.removeEventListener('beforetoggle', place, true);
      document.removeEventListener('toggle', flip, true);
    },
  };
}

/**
 * A menu closes when an item is chosen. In the capture phase, before the item's own handler: the
 * browser then hands focus back to the button that opened the menu, so a sheet the item opens
 * remembers that button, not a row that is about to disappear.
 */
export function popmenu(node) {
  const click = (e) => {
    if (!e.target.closest?.('.pm-menu__item')) return;
    if (node.tagName === 'DIALOG') node.close();
    else node.hidePopover?.();
  };
  node.addEventListener('click', click, true);
  return { destroy: () => node.removeEventListener('click', click, true) };
}

/**
 * Show a small glass pill at the bottom of the screen. `action` adds a button to it, usually
 * "Undo", and gives the reader longer: toast('Removed ✓', { action: { label: 'Undo', onClick } }).
 */
export function toast(message, { duration, action } = {}) {
  if (typeof document === 'undefined') return;
  let region = document.querySelector('.pm-toaster');
  const isNew = !region;
  if (isNew) {
    region = document.createElement('div');
    region.className = 'pm-toaster';
    region.setAttribute('role', 'status');
    region.setAttribute('aria-live', 'polite');
    document.body.appendChild(region);
  }
  const el = document.createElement('div');
  el.className = 'pm-toast';
  el.textContent = message;
  let button;
  const dismiss = () => {
    // Fading out isn't gone: a second click on Undo must not run it again.
    if (button) button.disabled = true;
    el.removeAttribute('data-pm-in');
    setTimeout(() => el.remove(), 400);
  };
  let timer;
  if (action) {
    button = document.createElement('button');
    button.type = 'button';
    button.className = 'pm-toast__action';
    button.textContent = action.label;
    button.addEventListener('click', () => { clearTimeout(timer); action.onClick?.(); dismiss(); });
    el.appendChild(button);
  }
  const show = () => {
    region.appendChild(el);
    requestAnimationFrame(() => requestAnimationFrame(() => el.setAttribute('data-pm-in', '')));
    timer = setTimeout(dismiss, duration ?? (action ? 6000 : 2200));
  };
  // A live region has to be there before its text, or many screen readers miss the first toast.
  if (isNew) setTimeout(show, 100);
  else show();
}

/**
 * A .pm-bars chart reads out the bar under the pointer, under a finger as it slides, or picked with
 * the arrow keys. Nothing changes until then: a chart the server rendered must still match when
 * React hydrates it, so the readout is CSS and the tabindex is the markup's.
 */
export function bars(node) {
  const items = () => Array.from(node.children);
  let current = null;

  const show = (bar) => {
    current?.removeAttribute('data-pm-active');
    current = bar;
    if (!bar) return;
    bar.setAttribute('data-pm-active', '');
    const box = node.getBoundingClientRect();
    const r = bar.getBoundingClientRect();
    const width = parseFloat(getComputedStyle(bar, '::after').width) || 0;
    const left = r.left + r.width / 2 - box.left - width / 2;
    node.style.setProperty('--pm-bars-x', `${Math.max(0, Math.min(left, box.width - width))}px`);
  };

  // By column, not by element: the whole width answers, gaps included.
  const over = (e) => {
    const all = items();
    const box = node.getBoundingClientRect();
    const i = Math.floor(((e.clientX - box.left) / box.width) * all.length);
    show(all[Math.max(0, Math.min(all.length - 1, i))]);
  };
  // A finger lifting leaves its reading up; a mouse leaving, or a tap elsewhere, clears it.
  const clear = () => show(null);
  const leave = (e) => { if (e.pointerType === 'mouse') clear(); };
  const outside = (e) => { if (current && !node.contains(e.target)) clear(); };
  const key = (e) => {
    const all = items();
    const i = all.indexOf(current);
    const to = { ArrowRight: i + 1, ArrowLeft: i < 0 ? all.length - 1 : i - 1, Home: 0, End: all.length - 1 }[e.key];
    if (e.key === 'Escape') clear();
    if (to === undefined) return;
    e.preventDefault();
    show(all[Math.max(0, Math.min(all.length - 1, to))]);
  };
  const focus = () => { if (node.matches(':focus-visible') && !current) show(items().at(-1)); };

  node.addEventListener('pointerdown', over);
  node.addEventListener('pointermove', over);
  node.addEventListener('pointerleave', leave);
  node.addEventListener('pointercancel', clear);
  node.addEventListener('keydown', key);
  node.addEventListener('focus', focus);
  node.addEventListener('blur', clear);
  document.addEventListener('pointerdown', outside);

  return {
    destroy() {
      node.removeEventListener('pointerdown', over);
      node.removeEventListener('pointermove', over);
      node.removeEventListener('pointerleave', leave);
      node.removeEventListener('pointercancel', clear);
      node.removeEventListener('keydown', key);
      node.removeEventListener('focus', focus);
      node.removeEventListener('blur', clear);
      document.removeEventListener('pointerdown', outside);
      clear();
      node.style.removeProperty('--pm-bars-x');
    },
  };
}

/** Attribute -> behavior table used by init(). */
export const behaviors = {
  'data-pm-reveal': reveal,
  'data-pm-stagger': stagger,
  'data-pm-tilt': tilt,
  'data-pm-cycle': cycle,
  'data-pm-copy': copy,
  'data-pm-countdown': countdown,
  'data-pm-open': opener,
  'data-pm-clear': clear,
  'data-pm-menu': menu,
};

/**
 * Wire every data-pm-* behavior inside `root`, now and as the DOM changes
 * (client-side routing, lazy lists). Call once at the app root. Returns cleanup.
 */
export function init(root = typeof document !== 'undefined' ? document : null, { observe = true } = {}) {
  if (!root) return () => {};
  const mounted = new Map(); // element -> Map(attribute -> handle)
  const dialogs = 'dialog.pm-dialog, dialog.pm-sheet, dialog.pm-panel, dialog.pm-fabmenu';
  const popovers = '.pm-menu[popover], dialog.pm-fabmenu';
  const selector = [...Object.keys(behaviors).map((a) => `[${a}]`), dialogs, popovers, '.pm-bars'].join(',');

  const mount = (el) => {
    let handles = mounted.get(el);
    if (!handles) mounted.set(el, (handles = new Map()));
    for (const [name, fn] of Object.entries(behaviors)) {
      if (el.hasAttribute(name) && !handles.has(name)) handles.set(name, fn(el));
    }
    if (el.matches(dialogs) && !handles.has('dialog')) handles.set('dialog', dialog(el));
    if (el.matches(popovers) && !handles.has('popmenu')) handles.set('popmenu', popmenu(el));
    if (el.matches('.pm-bars') && !handles.has('bars')) handles.set('bars', bars(el));
  };
  const scan = (node) => {
    if (node.nodeType !== 1) return;
    if (node.matches(selector)) mount(node);
    node.querySelectorAll(selector).forEach(mount);
  };
  const unmountDetached = () => {
    for (const [el, handles] of mounted) {
      if (el.isConnected) continue;
      handles.forEach((h) => h.destroy());
      mounted.delete(el);
    }
  };

  scan(root.nodeType === 9 ? root.documentElement : root);
  (root.nodeType === 9 ? root.documentElement : root.ownerDocument.documentElement).setAttribute('data-pm-ready', '');

  let mo;
  if (observe && typeof MutationObserver !== 'undefined') {
    mo = new MutationObserver((records) => {
      let removed = false;
      for (const rec of records) {
        rec.addedNodes.forEach(scan);
        if (rec.removedNodes.length) removed = true;
      }
      if (removed) unmountDetached();
    });
    mo.observe(root.nodeType === 9 ? root.documentElement : root, { childList: true, subtree: true });
  }

  return () => {
    mo?.disconnect();
    mounted.forEach((handles) => handles.forEach((h) => h.destroy()));
    mounted.clear();
  };
}
